	[102790]={ name="Oath of Retribution", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={102790,1027901,1027902,1027904,1027905,1027906,1027907,1027908}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="skill_icon_102720.png", desc="Upon action, <color=#ffb136>locks onto</color> the enemy with the lowest HP (prioritizes BOSS > Elite when targeting monsters). Allies deal <color=#18ec68>6</color>% increased damage to the locked target (self effect increased by <color=#18ec68>70</color>%). For every 25% HP lost by an enemy unit, self gains 1 stack of <color=#ffb136>Judgment</color>. When <color=#ffb136>Judgment</color> reaches 6 stacks, unleashes 1 Energy Burst on the locked target (no cost, triggered after current unit's skill). This damage <color=#ffb136>cannot be blocked</color>", desc_tips="", voice=0, skill_target=0, subtype=3, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[102880]={ name="Decree", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={102880,1028801,1028803,1028805,1028806,1028807}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="skill_icon_102810.png", desc="Yunzhuan gains 1 stack of <color=#ffb136>Floating Diagram</color> each time she acts, max 2 stacks. When an enemy acts and uses a skill attack, Yunzhuan consumes 1 stack of <color=#ffb136>Floating Diagram</color> to interrupt the enemy's battle flow and applies 1 stack of <color=#ffb136>Talisman Art</color> to them (target's ATK decreased by <color=#18ec68>8</color>%), lasting 2 turns, max 2 stacks. Each time <color=#ffb136>Floating Diagram</color> is activated, Yunzhuan's Elemental RES increases by <color=#18ec68>4</color>%, lasting until battle ends, max 5 stacks", desc_tips="", voice=0, skill_target=0, subtype=3, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[102890]={ name="Fortune Blessing", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={102890,1028901,1028902}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="skill_icon_102820.png", desc="Yunzhuan's Max HP permanently increases by <color=#18ec68>10</color>%. When hit by a skill attack, Yunzhuan has a <color=#18ec68>70</color>% chance to gain 1 stack of <color=#ffb136>Hexagram</color>, max 6 stacks. At max stacks, <color=#ffb136>Hexagram</color> converts into 1 stack of <color=#ffb136>Floating Diagram</color> (cannot convert while Floating Diagram exists)", desc_tips="", voice=0, skill_target=0, subtype=3, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[102980]={ name="Negative Charge", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={102980,1029801,1029804,1029806,1029812,1029814}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="skill_icon_102910.png", desc="At the start of each turn, randomly generates 1 Static Ball (invincible, occupies an empty tile, inherits <color=#18ec68>30</color>% of Morpho's <color=#ffb136>Offensive Stats</color>) around enemies, lasting 2 turns, max 3 balls. Enemy units within the 3x3 area of a Static Ball have SPD reduced by <color=#18ec68>3</color>% × <color=#ffb136>Electrode</color> stacks and Lightning RES reduced by <color=#18ec68>4</color>% × <color=#ffb136>Electrode</color> stacks (non-stacking, only the highest value applies). At the end of each turn, Static Balls discharge to <color=#ffb136>all enemies</color>, dealing Lightning damage equal to 30% of the Ball's ATK × <color=#ffb136>Electrode</color> stacks (can CRIT and receive DMG bonuses). When Morpho acts, provides 1 stack of <color=#ffb136>Electrode</color> to Static Balls. Each Ball can store up to 4 stacks of <color=#ffb136>Electrode</color>", desc_tips="", voice=0, skill_target=0, subtype=3, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
