	[101030]={ name="音符の煌めき", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={101030,1010301}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="skill_icon_101060.png", desc="エコーは1ターン目ににエネルギーを50%補充し、さらにアステバーストがメインターゲットにシンセバウンドを付与する確率が<color=#18ec68>24</color>%上昇する", desc_tips="", voice=0, skill_target=0, subtype=3, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
