	[7433]={ name="Sigil Effect", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={7433,74331,74332,74333,74334,74335,74336,74337,74338}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="", desc="Increases CRIT DMG by <color=#18ec68>14</color>%\nWhen equipped by Momiji, increases DMG to Shielded targets by <color=#18ec68>7.5</color>%. At battle start, Momiji gains <color=#18ec68>6</color> stacks of <color=#ffb136>Foxfire</color>. When consuming <color=#ffb136>Foxfire</color>, she has a <color=#18ec68>64</color>% chance to gain 1 additional stack of <color=#ffb136>Discernment</color>. Upon exiting Spirit Form, Momiji immediately gains <color=#18ec68>2</color> stacks of <color=#ffb136>Foxfire</color>, plus additional stacks equal to the number of fallen units on the field.", desc_tips="", voice=0, skill_target=0, subtype=0, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
