	[7434]={ name="Sigil Effect", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={7434,74341,74342,74343,74345,74346,74347,74348}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="", desc="Increases DEF Ignore by <color=#18ec68>8</color>%\nWhen equipped by Frost Knight·Dawn, at the start of each turn, she has a <color=#18ec68>40</color>% chance to gain 2 stacks of <color=#ffb136>Judgment</color>; otherwise gains 1 stack. Each time an enemy is defeated, all allies' ATK increases by <color=#18ec68>3</color>% (self effect increased by 50%), lasting until battle ends, max 4 stacks. Energy Burst triggered by Judgment has a <color=#18ec68>35</color>% chance to instantly execute units with HP below 2000 (not considered damage).", desc_tips="", voice=0, skill_target=0, subtype=0, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[7435]={ name="Sigil Effect", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={7435,74351,74352,74353,74354,74355}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="", desc="Increases CRIT DMG RES by <color=#18ec68>15</color>%\nWhen equipped by Yunzhuan, gains 50% energy recharge on the first turn. When using skills, she has a <color=#18ec68>50</color>% chance to gain 2 stacks of <color=#ffb136>Hexagram</color>; otherwise gains 1 stack. Each time Floating Diagram is activated, her Max HP increases by <color=#18ec68>5</color>%, lasting until battle ends, max 5 stacks.", desc_tips="", voice=0, skill_target=0, subtype=0, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[7436]={ name="Sigil Effect", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={7436,74361,74362,74363,74366,74367,74368}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="", desc="Increases CRIT Rate by <color=#18ec68>10</color>%\nWhen equipped by Morpho, generates +1 Static Ball on the first turn. When using Energy Skill, she has a <color=#18ec68>30</color>% chance to provide 2 stacks of <color=#ffb136>Electrode</color> to Static Balls; otherwise provides 1 stack. Additionally, after releasing Energy Burst, she has a <color=#18ec68>20</color>% chance to refresh the duration of Static Balls on the field.", desc_tips="", voice=0, skill_target=0, subtype=0, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[7437]={ name="Sigil Effect", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={7437,74371,74372,74373,74374,74376}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="", desc="Each time this unit acts, SPD increases by <color=#18ec68>3</color>% and Effect Hit Rate increases by <color=#18ec68>1.5</color>%, lasting until battle ends, max 4 stacks.\nWhen equipped by Kovneil, gains 50% energy recharge on the first turn and obtains +1 Gem Spirit. Energy Burst deals +<color=#18ec68>10</color>% Effect Hit Rate to the primary target. When using Energy Skill or Energy Burst, she has a 50% chance to obtain 1 random Gem Spirit.", desc_tips="", voice=0, skill_target=0, subtype=0, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
},
	[7438]={ name="Sigil Effect", type=4, round_limit=0, round_cd=0, cost=0, conditions={}, effect={7438,74381,74382,74383,74384}, extra_passive_effect={}, is_scene=0, animation="", skill_attr={}, icon="", desc="Increases CRIT Rate by <color=#18ec68>10</color>%\nWhen equipped by Windy, gains 50% energy recharge on the first turn. After using Energy Skill or Energy Burst, she has a <color=#18ec68>60</color>% chance to gain 1 additional stack of <color=#ffb136>Cyclone</color>. Additionally, the cooldown for units that receive <color=#ffb136>Monsoon</color> to obtain it again is reduced to <color=#18ec68>4</color> turns.", desc_tips="", voice=0, skill_target=0, subtype=0, location={}, gain_type=0, effect_type=0, camera_type=0, scope=0, skill_locate="", camera_focus=0
